-- Provenance of every CSV under capri_data: generated by tools/check/make_provenance.py from the pipeline's trace
-- (tools/pipeline/builders.json); do not edit by hand. Notes checked by a person: 02_provenance_notes.sql.

CREATE TABLE provenance (
    file VARCHAR PRIMARY KEY,
    nature VARCHAR NOT NULL CHECK (nature IN ('capri', 'capri-publication', 'external', 'mixed', 'source-extract', 'declared', 'no-builder')),
    origins VARCHAR NOT NULL,
    builder VARCHAR,
    sources VARCHAR,
    note VARCHAR
);
COMMENT ON TABLE provenance IS 'each data file: its nature, the origins of what its builders read, its builder, the files outside the repository its builder chain reads';
